import { Checkbox as CheckboxPrimitive } from '@fictjs/radix-ui'

import { cn } from '@/lib/cn'

type CheckboxProps = {
  class?: string
  indicatorClass?: string
  children?: unknown
  [key: string]: unknown
}

export function Checkbox(props: CheckboxProps) {
  const { class: className, indicatorClass, children, ...rest } = props

  return (
    <CheckboxPrimitive.Root
      class={cn(
        'peer h-4 w-4 shrink-0 rounded-sm border border-primary ring-offset-background data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50',
        className,
      )}
      {...rest}
    >
      <CheckboxPrimitive.Indicator class={cn('flex items-center justify-center text-[10px]', indicatorClass)}>
        {children ?? '✓'}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}
